import{_ as t,o,c as n,a4 as r}from"./chunks/framework.CmuCl-jw.js";const p=JSON.parse('{"title":"Alpaca Server on Another Windows Machine","description":"","frontmatter":{},"headers":[],"relativePath":"local/alpaca-lan.md","filePath":"local/alpaca-lan.md"}'),s={name:"local/alpaca-lan.md"};function a(i,e,l,c,d,h){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="alpaca-server-on-another-windows-machine" tabindex="-1">Alpaca Server on Another Windows Machine <a class="header-anchor" href="#alpaca-server-on-another-windows-machine" aria-label="Permalink to “Alpaca Server on Another Windows Machine”">​</a></h1><p>Follow these steps when the Alpaca server (ASCOM Remote, Alpaca Simulators, or any Alpaca-compatible server) runs on a <strong>Windows machine different from the one running Arcsecond.local</strong>, both on the same local network.</p><p>Everything below is done through graphical interfaces. No terminal command is required.</p><p>Throughout this page:</p><ul><li><code>192.168.1.42</code> stands for the IP address of the <strong>Windows machine running the Alpaca server</strong>.</li><li><code>11111</code> stands for the port of the Alpaca server (the ASCOM Remote default; Alpaca Simulators use <code>32323</code>).</li></ul><p>Replace both with your own values.</p><h2 id="_1-note-the-ip-address-of-the-windows-machine" tabindex="-1">1. Note the IP address of the Windows machine <a class="header-anchor" href="#_1-note-the-ip-address-of-the-windows-machine" aria-label="Permalink to “1. Note the IP address of the Windows machine”">​</a></h2><p>On the <strong>Windows machine running the Alpaca server</strong>:</p><ol><li>Open <strong>Settings → Network &amp; Internet</strong>.</li><li>Click <strong>Wi-Fi</strong> or <strong>Ethernet</strong>, depending on how the machine is connected.</li><li>Click the name of the network, then scroll down to <strong>IPv4 address</strong>.</li><li>Write that address down (e.g. <code>192.168.1.42</code>).</li></ol><h2 id="_2-fix-that-ip-address" tabindex="-1">2. Fix that IP address <a class="header-anchor" href="#_2-fix-that-ip-address" aria-label="Permalink to “2. Fix that IP address”">​</a></h2><ol><li>On the same page, next to <strong>IP assignment</strong>, click <strong>Edit</strong>.</li><li>Choose <strong>Manual</strong> in the drop-down.</li><li>Turn <strong>IPv4</strong> on.</li><li>Fill in: <ul><li><strong>IP address</strong>: the address noted at step 1.</li><li><strong>Subnet mask</strong>: <code>255.255.255.0</code>.</li><li><strong>Gateway</strong>: your router&#39;s address (usually the same address ending in <code>.1</code>, e.g. <code>192.168.1.1</code>).</li><li><strong>Preferred DNS</strong>: your router&#39;s address, or <code>1.1.1.1</code>.</li></ul></li><li>Click <strong>Save</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>If your router offers a &quot;DHCP reservation&quot; page, reserving the address there works just as well, and leaves the Windows settings untouched.</p></div><h2 id="_3-set-the-network-profile-to-private" tabindex="-1">3. Set the network profile to Private <a class="header-anchor" href="#_3-set-the-network-profile-to-private" aria-label="Permalink to “3. Set the network profile to Private”">​</a></h2><ol><li>Open <strong>Settings → Network &amp; Internet</strong>.</li><li>Click <strong>Wi-Fi</strong> or <strong>Ethernet</strong>, then the network name.</li><li>Under <strong>Network profile type</strong>, select <strong>Private network</strong>.</li></ol><h2 id="_4-make-the-alpaca-server-listen-on-the-network" tabindex="-1">4. Make the Alpaca server listen on the network <a class="header-anchor" href="#_4-make-the-alpaca-server-listen-on-the-network" aria-label="Permalink to “4. Make the Alpaca server listen on the network”">​</a></h2><h3 id="ascom-remote" tabindex="-1">ASCOM Remote <a class="header-anchor" href="#ascom-remote" aria-label="Permalink to “ASCOM Remote”">​</a></h3><ol><li>Start <strong>ASCOM Remote Server</strong>.</li><li>Click the <strong>Setup</strong> button.</li><li>Open the <strong>Server Configuration</strong> tab.</li><li>In <strong>Server IP address</strong>, select the address noted at step 1 (<code>192.168.1.42</code>) — <strong>not</strong> <code>127.0.0.1</code> and <strong>not</strong> <code>localhost</code>.</li><li>Leave <strong>Server IP Port</strong> at <code>11111</code>.</li><li>Tick <strong>Enable Alpaca Discovery and Management Interface</strong>.</li><li>Click <strong>OK</strong>.</li><li>A dialog titled <strong>&quot;HTTP listen permissions required&quot;</strong> appears. Click <strong>Yes</strong>, then <strong>Yes</strong> again on the Windows permission prompt. The server restarts on its own.</li><li>Back in the main window, click <strong>Start</strong>: the status must read <strong>Remote Server Up</strong>. Click <strong>Connect</strong> to connect the devices.</li></ol><h3 id="alpaca-simulators" tabindex="-1">Alpaca Simulators <a class="header-anchor" href="#alpaca-simulators" aria-label="Permalink to “Alpaca Simulators”">​</a></h3><ol><li>Start <strong>ASCOM Alpaca Simulators</strong>.</li><li>Open the web page it displays (by default <code>http://localhost:32323</code>).</li><li>Go to <strong>Server Settings</strong>.</li><li>Set the <strong>Server IP Address</strong> / binding to <strong>All interfaces</strong> (<code>0.0.0.0</code>), or to <code>192.168.1.42</code>.</li><li>Leave the port at <code>32323</code>, and tick the <strong>Alpaca Discovery</strong> option.</li><li>Click <strong>Save</strong>, then restart the application.</li></ol><h2 id="_5-open-the-port-in-the-windows-firewall" tabindex="-1">5. Open the port in the Windows firewall <a class="header-anchor" href="#_5-open-the-port-in-the-windows-firewall" aria-label="Permalink to “5. Open the port in the Windows firewall”">​</a></h2><p>When the Alpaca server starts for the first time, Windows may display a <strong>Windows Security Alert</strong>. If it does:</p><ol><li>Tick <strong>Private networks</strong>.</li><li>Click <strong>Allow access</strong>. You are done with this step.</li></ol><p>If no such dialog appeared, or if you clicked <em>Cancel</em>, create the rule by hand:</p><ol><li>Press the <strong>Windows key</strong>, type <em>firewall</em>, and open <strong>Windows Defender Firewall with Advanced Security</strong>.</li><li>In the left column, click <strong>Inbound Rules</strong>.</li><li>In the right column, click <strong>New Rule…</strong>.</li><li>Select <strong>Port</strong>, click <strong>Next</strong>.</li><li>Select <strong>TCP</strong>, then <strong>Specific local ports</strong>, and type <code>11111</code>. Click <strong>Next</strong>.</li><li>Select <strong>Allow the connection</strong>. Click <strong>Next</strong>.</li><li>Tick <strong>Private</strong> only (untick <strong>Domain</strong> and <strong>Public</strong>). Click <strong>Next</strong>.</li><li><strong>Name</strong>: <code>Alpaca server (TCP 11111)</code>. Click <strong>Finish</strong>.</li></ol><p>Repeat steps 3 to 8 a second time for Alpaca discovery, changing two values:</p><ul><li>At step 5, select <strong>UDP</strong> and type <code>32227</code>.</li><li>At step 8, name the rule <code>Alpaca discovery (UDP 32227)</code>.</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>If a third-party security suite is installed (Norton, Kaspersky, Bitdefender, ESET…), it has its own firewall. Open its interface and allow the same ports there too.</p></div><h2 id="_6-check-the-connection" tabindex="-1">6. Check the connection <a class="header-anchor" href="#_6-check-the-connection" aria-label="Permalink to “6. Check the connection”">​</a></h2><p>On the machine running <strong>Arcsecond.local</strong>, open a web browser and go to:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://192.168.1.42:11111/management/apiversions</span></span></code></pre></div><p>A short text response such as <code>{&quot;Value&quot;:[1],...}</code> means the connection works. If the page never loads, go back through steps 4 and 5.</p><h2 id="_7-register-the-server-in-arcsecond" tabindex="-1">7. Register the server in Arcsecond <a class="header-anchor" href="#_7-register-the-server-in-arcsecond" aria-label="Permalink to “7. Register the server in Arcsecond”">​</a></h2><ol><li><p>Open Arcsecond.local and go to the <strong>Control Room</strong>.</p></li><li><p>Click <strong>Start Registration…</strong> (or open the device registration panel from the Equipments tool).</p></li><li><p>On the <strong>Alpaca Server</strong> step, in the field following <code>http://</code>, type:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>192.168.1.42:11111</span></span></code></pre></div></li><li><p>Click <strong>Check</strong>. The server name, manufacturer and number of devices appear.</p></li><li><p>Click <strong>Register Server</strong>.</p></li><li><p>Click <strong>Next</strong> and continue with the <strong>Alpaca Devices</strong>, <strong>Telescope &amp; Mount</strong>, <strong>Other Equipments</strong> and <strong>Observing Setup</strong> steps.</p></li></ol><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Do not enter <code>localhost</code> or <code>127.0.0.1</code> in that field. Those addresses point to the machine running Arcsecond.local, not to the Windows machine hosting the Alpaca server.</p></div>',34)])])}const u=t(s,[["render",a]]);export{p as __pageData,u as default};
